import { FormEvent, useState } from 'react';

import queryString from 'query-string';
import { useLocation, useNavigate } from 'react-router-dom';

import { IUserRegistrationDTO, userRegistrationStart } from '@apps/Users/@services/user.services';
import notificationHelper, { error, success } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes, IPohInputProps } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

type Ty = IUserRegistrationDTO & {
  conf_pass: string;
};

const fieldsResource: Array<{ field: keyof Ty; props: IPohInputProps }> = [
  {
    field: 'name',
    props: {
      label: 'Имя',
      placeholder: 'Введите имя',
    },
  },
  {
    field: 'surname',
    props: {
      label: 'Фамилия',
      placeholder: 'Введите фамилию',
    },
  },
  {
    field: 'dob',
    props: {
      label: 'Дата рождения',
      placeholder: 'Введите ДР',
      type: InputTypes.date,
      min: new Date(Date.now() - 86400000 * 365 * 99).toISOString().substr(0, 10),
      max: new Date(Date.now() - 86400000 * 365 * 18).toISOString().substr(0, 10),
    },
  },
  {
    field: 'login',
    props: {
      label: 'Логин',
      placeholder: 'Введите логин',
    },
  },
  {
    field: 'email',

    props: {
      label: 'Email',
      type: InputTypes.email,
      placeholder: 'Введите email',
    },
  },
  {
    field: 'pass',
    props: {
      label: 'Пароль',
      placeholder: 'Введите пароль',
      type: InputTypes.password,
    },
  },
  {
    field: 'conf_pass',
    props: {
      label: 'Подтверждение',
      placeholder: 'Введите подтверждение пароля',
      type: InputTypes.password,
    },
  },
];

const Registration = () => {
  const location = useLocation();
  const navigate = useNavigate();

  const [data, setData] = useState<Ty>({
    name: '',
    surname: '',
    login: '',
    pass: '',
    conf_pass: '',
    dob: '',
    email: '',
  });

  const submitFormHandler = async (event: FormEvent) => {
    event.preventDefault();

    if (data.pass !== data.conf_pass) {
      error('Введенные пароли не совпадают');
      document.getElementById('conf_pass')?.focus();
      return;
    }
    try {
      const result = await userRegistrationStart(data);
      if (result && result.user) {
        success('Вы успешно зарегистрировались!');
        const search = queryString.parse(location.search) || {};

        navigate((search.return as string) || '/profile');
      }
    } catch (errr) {
      notificationHelper.error((errr as Error).message);
    }
  };

  return (
    <PohContainer>
      <form onSubmit={submitFormHandler}>
        <PohRow>
          <PohCol lg={{ span: 8, offset: 2 }}>
            <PohRow>
              <PohCol lg={{ span: 8, offset: 4 }} sm={{ offset: 4 }}>
                <h2 className="mb-4">Регистрация</h2>
              </PohCol>
            </PohRow>

            {fieldsResource.map(({ field, props }) => (
              <PohInput
                id={field}
                key={field}
                name={field}
                value={data[field]}
                onChange={(val) => setData({ ...data, [field]: val })}
                labelClassName="text-md-end"
                required
                horizontal
                {...props}
                inputGrid={8}
                labelGrid={4}
                wrapperClassName="mb-2"
              />
            ))}
            <PohRow className="mt-4">
              <PohCol lg={{ span: 8, offset: 4 }} sm={{ offset: 4 }}>
                <PohButton variant={ButtonVariant.Primary} type="submit" onClick={() => {}}>
                  Зарегистрироваться
                </PohButton>
              </PohCol>
            </PohRow>
          </PohCol>
        </PohRow>
      </form>
    </PohContainer>
  );
};

export default Registration;
